PREFIX crm: <http://www.cidoc-crm.org/cidoc-crm/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?obj ?objLabel ?type ?material ?page ?manifest WHERE {
  ?prod crm:P14_carried_out_by <https://data.getty.edu/museum/collection/person/8c408d42-49f4-4be9-9e8a-83506d9c4334> .
  ?obj crm:P108i_was_produced_by ?prod ;
       rdfs:label ?objLabel .
  OPTIONAL { ?obj crm:P2_has_type ?type }
  OPTIONAL { ?obj crm:P45_consists_of ?material }
  OPTIONAL { ?obj crm:P129i_is_subject_of ?page . FILTER(CONTAINS(STR(?page), '/art/collection/object/')) }
  OPTIONAL { ?obj crm:P129i_is_subject_of ?manifest . FILTER(CONTAINS(STR(?manifest), '/iiif/manifest/3/')) }
}
ORDER BY STR(?obj)

